// Spatial Locality (Cache Friendly Matrix Access)
#define N 1024
int matrix[N][N];

// Row-major iteration (C/C++ default)
// Sequential memory access: maximizes use of
// data brought into cache lines.
void process_rows() {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            matrix[i][j] = 0;
        }
    }
}
// Note: Looping j then i (column-major) causes
// poor spatial locality and cache thrashing.

// Cache Line Optimization (False Sharing Prevention)
#define CACHE_L_SIZE 64 // Typical L1/L2 Cache Line Size

// Ensures structures do not share cache lines
struct __attribute__((aligned(CACHE_L_SIZE))) PerThreadData {
    long operation_count;
    // Implicit padding fills remainder of 64 bytes
};

PerThreadData status[8];
// status[i] modified only by Thread i
// Avoids coherence invalidation overheads.
